def fact(n):
    return 1 if n <= 1 else n * fact(n - 1)

for n in (0, 1, 5, 20, 21, 25, 30, 50):
    print(n, fact(n))
print(fact(100) // fact(98), len(str(fact(200))), fact(30) % 1000000007)
print(2 ** 10, 2 ** 64, 2 ** 100, 3 ** 50, 10 ** 30, (-2) ** 63, (-2) ** 64, 7 ** 0, 0 ** 0, (-1) ** 101)
print(2 ** 62 + 2 ** 62, -2 ** 63 - 1, 9223372036854775807 + 1, -9223372036854775808 - 1)
x = 1
for i in range(70):
    x *= 2
print(x, x - 1, x + 1, x // 3, x % 1000, -x // 3, -x % 1000)
